<section class="page-heading">
    <div><div class="eyebrow">Access control</div><h1>Super Admins</h1><p>Every authenticated account has the same Super Admin permission tier. There are no editor or approver roles.</p></div>
    <div class="heading-actions"><button class="button button-primary" type="button" data-open-modal="user-modal"><i class="fa-solid fa-user-plus"></i><span>Add administrator</span></button></div>
</section>
<section class="panel"><div class="table-wrap"><table class="data-table"><caption class="visually-hidden">Super Admin accounts and their access status</caption><thead><tr><th scope="col">Name</th><th scope="col">Email</th><th scope="col">Access tier</th><th scope="col">Status</th><th scope="col">Actions</th></tr></thead><tbody id="users-table"><tr><td colspan="5" class="table-loading"><i class="fa-solid fa-circle-notch fa-spin"></i><span>Loading administrators</span></td></tr></tbody></table></div></section>
<div class="modal" id="user-modal" role="dialog" aria-modal="true" aria-labelledby="user-title"><div class="modal-dialog"><div class="modal-header"><h2 id="user-title">Add Super Admin</h2><button class="icon-button" type="button" data-modal-close aria-label="Close"><i class="fa-solid fa-xmark"></i></button></div><form id="user-form"><div class="modal-body"><div class="form-grid"><div class="form-field form-field-full"><label for="user-name">Full name <span>*</span></label><input id="user-name" name="full_name" required><span class="field-error" data-error-for="full_name"></span></div><div class="form-field form-field-full"><label for="user-email">Email <span>*</span></label><input id="user-email" name="email" type="email" required><span class="field-error" data-error-for="email"></span></div><div class="form-field form-field-full"><label for="user-password">Password <span>*</span></label><input id="user-password" name="password" type="password" minlength="8" required><span class="field-error" data-error-for="password"></span></div><div class="form-field form-field-full"><label for="user-phone">Phone</label><input id="user-phone" name="phone_number" type="tel" placeholder="+254700000000"><span class="field-error" data-error-for="phone_number"></span></div><div class="form-field"><label for="user-active">Status</label><select id="user-active" name="is_active"><option value="1">Active</option><option value="0">Inactive</option></select></div></div></div><div class="modal-footer"><button class="button button-secondary" type="button" data-modal-close>Cancel</button><button class="button button-primary" type="submit"><i class="fa-solid fa-check"></i><span>Save administrator</span></button></div></form></div></div>
